function ensureBank(bank){const base=sanitizeBank(bank);if(base.length>=1000)return base.slice(0,1000);const seen=new Set(base.map(x=>x.q));for(const q of defaultQuestions()){if(base.length>=1000)break;if(!seen.has(q.q)){base.push(q);seen.add(q.q);}}return base.slice(0,1000);}
function pub(g,role){
  const base={code:g.code,teams:g.teams.map(t=>({id:t.id,name:t.name,score:t.score,strikes:t.strikes,doubleUsed:!!t.doubleUsed,doubleActive:!!t.doubleActive,doublePlayer:t.doublePlayer||'',players:t.players.map(p=>({name:p.name}))})),rounds:g.rounds,time:g.time,currentRound:g.currentRound,question:g.question,phase:g.phase,timer:g.timer,lock:g.lock};
  if(role==='host'){
    return {...base,answers:g.answers,questionBank:g.questionBank||[]};
  }
  return {...base,answers:(g.answers||[]).map(a=>a.revealed?{text:a.text,points:a.points,revealed:true}:{revealed:false})};
}
async function save(g){if(!pool)return;await pool.query(`INSERT INTO games(code,state,updated_at) VALUES($1,$2,NOW()) ON CONFLICT(code) DO UPDATE SET state=$2,updated_at=NOW()`,[g.code,JSON.stringify({...g,host:null,displays:[],teams:g.teams.map(t=>({...t,players:[]}))})]).catch(console.error)}
async function init(){if(!pool)return;await pool.query(`CREATE TABLE IF NOT EXISTS games(code TEXT PRIMARY KEY,state JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);const rs=await pool.query(`SELECT code,state FROM games WHERE updated_at>NOW()-INTERVAL '24 hours'`);for(const r of rs.rows){const g=r.state;g.code=r.code;g.host=null;g.displays=new Set();g.teams.forEach(t=>t.players=[]);g.questionBank=ensureBank(g.questionBank||defaultQuestions());if(Array.isArray(g.answers))g.answers=g.answers.map((a,order)=>({...a,_order:order})).sort((a,b)=>Number(b.points||0)-Number(a.points||0)||a._order-b._order).map(({_order,...a})=>a);g.teams.forEach(t=>{t.doubleUsed=!!t.doubleUsed;t.doubleActive=!!t.doubleActive;t.doublePlayer=t.doublePlayer||'';});games.set(g.code,g)}}
function emit(g){
  const room=io.sockets.adapter.rooms.get(g.code)||new Set();
  for(const sid of room){
    const sock=io.sockets.sockets.get(sid);
    if(sock) sock.emit('state',pub(g,sock.data?.role));
  }
  save(g);
}function get(c){return games.get(clean(c))}
io.on('connection',s=>{
 s.on('host:create',async({rounds=5,teamA,teamB}={})=>{const g=fresh(),p=pin();g.host=s.id;g.hostPinHash=hash(p);g.rounds=Math.min(50,Math.max(1,+rounds||5));if(teamA)g.teams[0].name=String(teamA).trim().slice(0,30)||g.teams[0].name;if(teamB)g.teams[1].name=String(teamB).trim().slice(0,30)||g.teams[1].name;games.set(g.code,g);s.join(g.code);s.data={role:'host',game:g.code};await save(g);s.emit('game:created',{code:g.code,pin:p});emit(g)});
 s.on('host:rejoin',({code,pin}={})=>{const g=get(code);if(!g||!g.hostPinHash||hash(pin)!==g.hostPinHash)return s.emit('error:msg','رمز المقدم غير صحيح');g.host=s.id;g.questionBank=ensureBank(g.questionBank||defaultQuestions());if(Array.isArray(g.answers))g.answers=g.answers.map((a,order)=>({...a,_order:order})).sort((a,b)=>Number(b.points||0)-Number(a.points||0)||a._order-b._order).map(({_order,...a})=>a);s.join(g.code);s.data={role:'host',game:g.code};s.emit('host:rejoined');emit(g)});
 s.on('display:join',({code}={})=>{const g=get(code);if(!g)return s.emit('error:msg','رمز اللعبة غير صحيح');g.displays.add(s.id);s.join(g.code);s.data={role:'display',game:g.code};s.emit('display:joined');emit(g)});
 s.on('player:lookup',({code}={})=>{const g=get(code);if(!g)return s.emit('error:msg','رمز اللعبة غير صحيح');s.emit('player:teams',g.teams.map(t=>({id:t.id,name:t.name})));});
 s.on('player:join',({code,name,team}={})=>{const g=get(code),t=g?.teams.find(x=>x.id===team),n=String(name||'').trim().slice(0,24);if(!g)return s.emit('error:msg','رمز اللعبة غير صحيح');if(!t)return s.emit('error:msg','اختر فريقًا');if(!n)return s.emit('error:msg','اكتب اسمك');g.teams.forEach(x=>x.players=x.players.filter(p=>p.socketId!==s.id));t.players.push({socketId:s.id,name:n});s.join(g.code);s.data={role:'player',game:g.code,team,name:n};s.emit('player:joined',{team,name:n});emit(g)});
 s.on('buzzer:press',({code}={})=>{const g=get(code);if(!g||s.data.game!==g.code||s.data.role!=='player'||g.phase!=='question'||g.lock)return;const t=g.teams.find(x=>x.id===s.data.team);if(!t||t.strikes>=3)return;g.lock={name:s.data.name,team:s.data.team};io.to(g.code).emit('buzzer:locked',g.lock);emit(g);setTimeout(()=>{const cur=games.get(g.code);if(cur&&cur.lock&&cur.lock.name===g.lock.name&&cur.lock.team===g.lock.team){cur.lock=null;emit(cur)}},3000)});
 s.on('host:startRound',({code,question,answers,questionIndex}={})=>{const g=get(code);if(!g||g.host!==s.id||g.currentRound>=g.rounds)return;let item=(Number.isInteger(questionIndex)&&g.questionBank[questionIndex])?g.questionBank[questionIndex]:null;if(item){question=item.q;answers=item.a.map(x=>({text:x[0],points:x[1]}));}g.currentRound++;g.questionIndex=Number.isInteger(questionIndex)?questionIndex:g.questionIndex;g.question=String(question||'').slice(0,200);g.answers=(Array.isArray(answers)?answers:[]).slice(0,8).map((a,order)=>({text:String(a.text||'').slice(0,80),points:Math.max(0,+a.points||0),revealed:false,awarded:false,_order:order})).sort((a,b)=>b.points-a.points||a._order-b._order).map(({_order,...a})=>a);g.phase='question';g.lock=null;emit(g)});
 s.on('host:saveBank',({code,bank}={})=>{const g=get(code);if(!g||g.host!==s.id)return;const cleanBank=sanitizeBank(bank);if(!cleanBank.length)return s.emit('error:msg','يجب أن تحتوي قاعدة الأسئلة على سؤال وإجابة واحدة على الأقل');g.questionBank=ensureBank(cleanBank);emit(g);s.emit('bank:saved');});
 s.on('host:addQuestion',({code,question}={})=>{const g=get(code);if(!g||g.host!==s.id)return;const b=sanitizeBank([...(g.questionBank||[]),question]);if(b.length>(g.questionBank||[]).length){g.questionBank=b;emit(g)}else s.emit('error:msg','السؤال أو الإجابات غير صالحة');});
 s.on('host:deleteQuestion',({code,index}={})=>{const g=get(code);if(!g||g.host!==s.id)return;g.questionBank=(g.questionBank||[]).filter((_,i)=>i!==index);if(!g.questionBank.length)g.questionBank=defaultQuestions();emit(g)});
 s.on('host:clearRound',({code}={})=>{const g=get(code);if(!g||g.host!==s.id)return;g.question='';g.answers=[];g.lock=null;g.phase='lobby';emit(g)});
 s.on('host:reveal',({code,index}={})=>{const g=get(code);if(!g||g.host!==s.id||!g.answers[index])return;g.answers[index].revealed=true;emit(g)});
 s.on('host:award',({code,team,points,answerIndex}={})=>{const g=get(code);if(!g||g.host!==s.id)return;const t=g.teams.find(x=>x.id===team);if(!t)return;const idx=Number(answerIndex);const a=Number.isInteger(idx)?g.answers?.[idx]:null;if(a&&a.awarded)return;const base=Math.max(0,+points||0);const multiplier=t.doubleActive?2:1;const awardedPoints=base*multiplier;t.score+=awardedPoints;if(a)a.awarded=true;
    // If the answer goes to the other team, cancel any active double immediately.
    g.teams.forEach(x=>{if(x.doubleActive)x.doubleActive=false;});
    io.to(g.code).emit('answer:awarded',{team:t.id,answerIndex:idx,points:awardedPoints});emit(g)});
 s.on('player:double',({code}={})=>{const g=get(code);if(!g||s.data.game!==g.code||s.data.role!=='player'||g.phase!=='question')return;const t=g.teams.find(x=>x.id===s.data.team);if(!t||t.doubleUsed)return;t.doubleUsed=true;t.doubleActive=true;t.doublePlayer=s.data.name;io.to(g.code).emit('double:activated',{team:t.id,name:s.data.name});emit(g)});
 s.on('host:strike',({code,team}={})=>{const g=get(code);if(!g||g.host!==s.id)return;const t=g.teams.find(x=>x.id===team);if(t)t.strikes=Math.min(3,t.strikes+1);emit(g)});
 s.on('host:resetStrikes',({code,team}={})=>{const g=get(code);if(!g||g.host!==s.id)return;const t=g.teams.find(x=>x.id===team);if(t)t.strikes=0;emit(g)});
 s.on('host:resetScores',({code}={})=>{const g=get(code);if(!g||g.host!==s.id)return;g.teams.forEach(t=>t.score=0);emit(g)});
 s.on('host:next',({code}={})=>{const g=get(code);if(!g||g.host!==s.id)return;g.phase=g.currentRound>=g.rounds?'finished':'lobby';g.question='';g.answers=[];g.lock=null;g.teams.forEach(t=>t.strikes=0);emit(g)});
 s.on('host:nextQuestion',({code}={})=>{const g=get(code);if(!g||g.host!==s.id||g.phase==='finished')return;const start=Math.max(-1,g.questionIndex);let idx=start+1;if(idx>=g.questionBank.length)idx=0;let guard=0;while(guard<g.questionBank.length&&g.questionBank[idx]?.q===g.question){idx=(idx+1)%g.questionBank.length;guard++;}const item=g.questionBank[idx];if(!item)return;g.currentRound++;g.questionIndex=idx;g.question=item.q;g.answers=item.a.map((x,order)=>({text:x[0],points:x[1],revealed:false,awarded:false,_order:order})).sort((a,b)=>b.points-a.points||a._order-b._order).map(({_order,...a})=>a);g.phase='question';g.lock=null;g.teams.forEach(t=>t.strikes=0);emit(g)});s.on('host:end',({code}={})=>{const g=get(code);if(!g||g.host!==s.id)return;g.phase='finished';g.lock=null;emit(g)});
 s.on('disconnect',()=>{const g=games.get(s.data?.game);if(!g)return;g.teams.forEach(t=>t.players=t.players.filter(p=>p.socketId!==s.id));g.displays.delete(s.id);if(g.host===s.id)g.host=null;emit(g)})
});
const PORT=+process.env.PORT||3000;init().then(()=>server.listen(PORT,'0.0.0.0',()=>console.log('Family Feud V7 on '+PORT))).catch(e=>{console.error(e);process.exit(1)});
